# owner: platform
import unittest

from rosterkit.notices import absence_notice
from rosterkit.models import Mark, Student
from rosterkit.errors import ProjectError
from datetime import date

STUDENT = Student("1", "Lee", "Ana", "A")


def mark(day, status="absent", student_id="1"):
    return Mark(student_id, date(2026, 9, day), status)


class NoticeTests(unittest.TestCase):
    def test_lists_absent_days_in_order(self):
        marks = [mark(9), mark(3), mark(4, "present")]
        text = absence_notice(STUDENT, marks)
        self.assertEqual(text, "Ana Lee missed 2 day(s): 2026-09-03, 2026-09-09.")

    def test_other_student_rejected(self):
        with self.assertRaises(ProjectError):
            absence_notice(STUDENT, [mark(3), mark(4, student_id="2")])

    def test_no_absences_rejected(self):
        with self.assertRaises(ProjectError):
            absence_notice(STUDENT, [mark(3, "late")])
